/**
 * Xpand Printer Agent — core HTTP server + raw printing.
 *
 * Listens on http://127.0.0.1:<port> (default 9101) and receives label streams
 * generated by the Xpand ERP (ZPL/TSPL/ESC/P) and prints them raw to the chosen
 * label printer through the OS driver. A small UI mirrors the BigSeller plugin:
 * pick the printer, pause the queue, and watch the recent job log.
 *
 * Endpoints:
 *   GET  /health     -> { ok, version, printer, paused, queueLength, printerModule }
 *   GET  /printers   -> { printers: [...] }
 *   GET  /config     -> { port, printer, paused }
 *   POST /config     -> { port?, printer?, paused? }  (persisted)
 *   GET  /jobs       -> { jobs: [...] }               (recent, newest first)
 *   POST /pause      -> pause=true | pause=false
 *   POST /print      -> { language, data } -> { ok, printer, bytes } | error
 *
 * Everything is bound to 127.0.0.1 only.
 */
'use strict';

const http = require('http');
const fs = require('fs');
const path = require('path');

// Maintained node-printer fork (prebuilt binaries) for raw printing to the OS
// spooler. Kept optional so the agent still boots without the native piece.
let printerLib = null;
try {
  printerLib = require('@thiagoelg/node-printer');
} catch (e) {
  printerLib = null;
}

const DEFAULT_PORT = 9101;
const MAX_JOB_LOG = 100;
const AGENT_VERSION = (() => {
  try {
    return require('./package.json').version || '0.0.0';
  } catch (e) {
    return '0.0.0';
  }
})();

// Auto-retry for transient print failures (printer busy, spooler hiccup).
// Deterministic errors (paused / no binding / no printer) are never retried.
const PRINT_RETRY_LIMIT = 2; // total attempts = retry limit + 1
const PRINT_RETRY_DELAY_MS = 1000;

function isRetryable(error) {
  return !/paused|not installed|printer module|no printer selected/i.test(String(error || ''));
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// Attempt a single raw print; resolves {ok, error, bytes}.
function attemptPrint(data, printer) {
  return new Promise((resolve) => {
    let resolved = false;
    const done = (ok, error, bytes) => {
      if (!resolved) {
        resolved = true;
        resolve({ ok, error, bytes });
      }
    };

    printerLib.printDirect(
      {
        data: Buffer.from(data, 'utf8'),
        printer,
        type: 'RAW',
        success: () => done(true, null, Buffer.byteLength(data)),
        error: (err) => done(false, String(err && err.message ? err.message : err), 0),
      }
    );
  });
}

// Serialize raw prints so concurrent POST /print jobs never interleave
// on the spooler. Each job chains onto the tail of the queue.
let printQueue = Promise.resolve();

function enqueuePrint(data, printer) {
  const run = printQueue.then(() => printWithRetry(data, printer));
  // Keep the chain alive even if a job throws; the caller awaits `run`.
  printQueue = run.catch(() => {});
  return run;
}

// Try printing with retry on transient failures; logs the final outcome once.
async function printWithRetry(data, printer) {
  let last = { ok: false, error: 'printing failed', bytes: 0 };

  for (let attempt = 0; attempt <= PRINT_RETRY_LIMIT; attempt++) {
    const result = await attemptPrint(data, printer);
    if (result.ok || !isRetryable(result.error) || attempt === PRINT_RETRY_LIMIT) {
      last = result;
      break;
    }
    if (attempt < PRINT_RETRY_LIMIT) await sleep(PRINT_RETRY_DELAY_MS);
  }

  return last;
}

const state = {
  port: DEFAULT_PORT,
  printer: null, // explicit printer name; null => OS default
  paused: false,
  jobs: [],
  configPath: path.join(__dirname, '.agent-config.json'),
};

function loadConfig() {
  try {
    const raw = fs.readFileSync(state.configPath, 'utf8');
    const data = JSON.parse(raw);
    if (Number.isInteger(data.port) && data.port > 0 && data.port < 65536) state.port = data.port;
    if (typeof data.printer === 'string') state.printer = data.printer || null;
    if (typeof data.paused === 'boolean') state.paused = data.paused;
  } catch (e) {
    /* first run: no config yet */
  }
}

function saveConfig() {
  try {
    fs.writeFileSync(state.configPath, JSON.stringify({ port: state.port, printer: state.printer, paused: state.paused }, null, 2));
  } catch (e) {
    console.error('Unable to persist agent config:', e.message);
  }
}

function getPort() {
  return state.port;
}

function setConfig(next) {
  if (Number.isInteger(next.port) && next.port > 0 && next.port < 65536) {
    state.port = next.port;
    restartServerIfRunning();
  }
  if (typeof next.printer === 'string') state.printer = next.printer.trim().slice(0, 256) || null;
  if (next.printer === null) state.printer = null;
  if (typeof next.paused === 'boolean') state.paused = next.paused;
  saveConfig();
}

function logJob(entry) {
  state.jobs.unshift(entry);
  if (state.jobs.length > MAX_JOB_LOG) state.jobs.length = MAX_JOB_LOG;
}

function getDefaultPrinterName() {
  if (!printerLib) return null;
  if (typeof printerLib.getDefaultPrinterName === 'function') {
    return printerLib.getDefaultPrinterName();
  }
  if (typeof printerLib.getDefaultPrinter === 'function') {
    return printerLib.getDefaultPrinter();
  }
  return null;
}

function effectivePrinter() {
  return state.printer || getDefaultPrinterName();
}

// Best-effort stream language hint from the selected printer name, so the ERP
// builds the right format (ZPL/TSPL/ESC/P) without asking the user.
function detectLanguage(printerName) {
  const n = String(printerName || '').toLowerCase();
  if (/zebra|zdesigner|zpl|\bzt[0-9]+/.test(n)) return 'zpl';
  if (/tsc|datamax|ttp|tek|tsp/.test(n)) return 'tspl';
  if (/esc\/p|epson|lq[0-9]+|fx[0-9]+|dot[ -]?matrix/.test(n)) return 'esc';
  return 'zpl';
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk) => {
      body += chunk;
      if (body.length > 2_000_000) {
        req.destroy();
        reject(new Error('Payload too large'));
      }
    });
    req.on('end', () => resolve(body));
    req.on('error', reject);
  });
}

function json(res, status, payload) {
  const body = JSON.stringify(payload);
  applyCors(res);
  res.writeHead(status, { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) });
  res.end(body);
}

// The agent only binds to 127.0.0.1, so allowing any origin is safe: it lets the
// operator's own ERP page (hosted anywhere) post print jobs straight to their PC.
function applyCors(res) {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
}

async function handlePrint(req, res) {
  if (state.paused) {
    logJob({ at: new Date().toISOString(), printer: state.printer, bytes: 0, ok: false, error: 'Agent is paused' });
    return json(res, 409, { ok: false, error: 'Agent is paused' });
  }

  if (!printerLib) {
    logJob({ at: new Date().toISOString(), printer: null, bytes: 0, ok: false, error: 'printer module not installed' });
    return json(res, 503, { ok: false, error: 'The printer binding is not loaded. Reinstall the latest agent installer for your OS, or (if running from source) run "npm install" then "npm run rebuild" and restart.' });
  }

  let payload;
  try {
    payload = JSON.parse(await readBody(req));
  } catch (e) {
    return json(res, 400, { ok: false, error: 'Invalid JSON body' });
  }

  const data = typeof payload.data === 'string' ? payload.data : '';
  if (!data) {
    return json(res, 400, { ok: false, error: 'Missing "data" field' });
  }

  const language = typeof payload.language === 'string' ? payload.language.toLowerCase().slice(0, 16) : null;
  const printer = payload.printer || effectivePrinter();

  if (!printer) {
    logJob({ at: new Date().toISOString(), printer: null, language, bytes: 0, ok: false, error: 'No printer selected — pick a printer in the Agent window first' });
    return json(res, 400, { ok: false, error: 'No printer selected — pick a printer in the Agent window first' });
  }

  const expected = detectLanguage(printer);
  const mismatch = language && language !== expected
    ? ` (language mismatch: job is ${language}, printer looks like ${expected})`
    : '';
  const result = await enqueuePrint(data, printer);

  if (result.ok) {
    logJob({ at: new Date().toISOString(), printer, language, bytes: result.bytes, ok: true, error: mismatch ? 'Warning' + mismatch : null });
    return json(res, 200, { ok: true, printer, bytes: result.bytes, warning: mismatch || undefined });
  }

  logJob({ at: new Date().toISOString(), printer, language, bytes: 0, ok: false, error: result.error + mismatch });
  return json(res, 502, { ok: false, error: result.error + mismatch });
}

let server = null;
let onRestart = null;

function createServer() {
  server = http.createServer(async (req, res) => {
    const url = new URL(req.url, `http://${req.headers.host || '127.0.0.1'}`);

    const get = url.searchParams.get.bind(url.searchParams);

    try {
      if (req.method === 'OPTIONS') {
        applyCors(res);
        res.writeHead(204);
        return res.end();
      }

      if (req.method === 'GET' && url.pathname === '/health') {
        const printer = effectivePrinter();
        return json(res, 200, {
          ok: true,
          version: AGENT_VERSION,
          printer,
          configuredPrinter: state.printer,
          detectedLanguage: detectLanguage(printer),
          paused: state.paused,
          jobs: state.jobs.length,
          queueLength: 0,
          port: state.port,
          printerModule: !!printerLib,
        });
      }

      if (req.method === 'GET' && url.pathname === '/printers') {
        const printers = printerLib && printerLib.getPrinters ? printerLib.getPrinters() : [];
        const names = (printers || []).map((p) => p.name).filter(Boolean);
        return json(res, 200, {
          printers: names,
          languages: names.map((n) => ({ printer: n, language: detectLanguage(n) })),
        });
      }

      if (req.method === 'GET' && url.pathname === '/config') {
        return json(res, 200, { port: state.port, printer: state.printer, paused: state.paused });
      }

      if (req.method === 'POST' && url.pathname === '/config') {
        let body;
        try {
          body = JSON.parse(await readBody(req));
        } catch (e) {
          return json(res, 400, { ok: false, error: 'Invalid JSON body' });
        }
        setConfig(body);
        return json(res, 200, { ok: true, port: state.port, printer: state.printer, paused: state.paused });
      }

      if (req.method === 'GET' && url.pathname === '/jobs') {
        return json(res, 200, { jobs: state.jobs });
      }

      if (req.method === 'POST' && url.pathname === '/pause') {
        const p = get('pause');
        if (p === null) state.paused = !state.paused;
        else state.paused = p !== 'false' && p !== '0' && p !== '';
        saveConfig();
        return json(res, 200, { ok: true, paused: state.paused });
      }

      if (req.method === 'POST' && url.pathname === '/print') {
        return await handlePrint(req, res);
      }

      return json(res, 404, { ok: false, error: 'Not found' });
    } catch (e) {
      return json(res, 500, { ok: false, error: String(e && e.message ? e.message : e) });
    }
  });

  return server;
}

// When the port changes, keep the HTTP server bounded to a single known port.
function restartServerIfRunning() {
  if (server && onRestart) {
    onRestart();
  }
}

function start() {
  if (server && server.listening) server.close();
  createServer().listen(state.port, '127.0.0.1', () => {
    console.log(`Xpand Printer Agent listening on http://127.0.0.1:${state.port}`);
  });
  return server;
}

function stop() {
  if (server) server.close();
  server = null;
}

// Callback used by the Electron wrapper to bind the server to the (possibly
// changed) configured port.
function attachRestart(handler) {
  onRestart = handler;
}

if (require.main === module) {
  loadConfig();
  createServer().listen(state.port, '127.0.0.1', () => {
    console.log(`Xpand Printer Agent listening on http://127.0.0.1:${state.port}`);
  });
}

module.exports = {
  createServer,
  start,
  stop,
  attachRestart,
  loadConfig,
  saveConfig,
  setConfig,
  getPort,
  getEffectivePrinter: effectivePrinter,
  getJobs: () => state.jobs,
  getState: () => ({ port: state.port, printer: state.printer, paused: state.paused }),
  DEFAULT_PORT,
};